const BUS = ['.Y...Y.', 'KBWWWBK', 'KBBBBBK', 'KBDDDBK', 'KBBBBBK', 'KBDDDBK', 'KBBBBBK', 'KBDDDBK', 'KBBBBBK', 'KBDDDBK', 'KBBBBBK', 'KBDDDBK', 'KBBBBBK', 'KBDDDBK', 'KBBBBBK', 'KBDDDBK', 'KBBBBBK', '.T...T.']
